mapper.select:
select fin.FINPROD_ID             
from FIN_PRODUCT fin
where fin.FINPROD_MARKET_ID = #{productcode,jdbcType=VARCHAR}
and DATE_FORMAT(fin.VDATE,'%Y%m%d') = #{establishdate,jdbcType=VARCHAR} 
and DATE_FORMAT(fin.MDATE,'%Y%m%d') = #{expirydate,jdbcType=VARCHAR} 
and fin.FINPROD_TYPE2 = #{prodType2,jdbcType=VARCHAR}
